namespace sv_7f841ba492954bfa9948c0c3004728d6.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

public class ThemeInfo
{
    public Theme Theme { get; set; } = Theme.Light;
    public string AccentColor { get; set; } = "#0d6efd";

    public ThemeInfo Clone() => new() { Theme = Theme, AccentColor = AccentColor };
}

using Microsoft.AspNetCore.Components;

namespace sv_7f841ba492954bfa9948c0c3004728d6.Services;

/// <summary>
/// Scoped service (per-circuit) that holds theme state and notifies subscribers on change.
/// Also synchronises the DI-registered CascadingValueSource so [CascadingParameter] consumers update.
/// </summary>
public class ThemeService
{
    private readonly CascadingValueSource<ThemeInfo> _cascadingSource;

    public ThemeService(CascadingValueSource<ThemeInfo> cascadingSource)
    {
        _cascadingSource = cascadingSource;
    }

    public ThemeInfo Current { get; private set; } = new();

    public event Action? OnChange;

    public async Task SetThemeAsync(Theme theme)
    {
        Current.Theme = theme;
        await NotifyAsync();
    }

    public async Task SetAccentColorAsync(string accentColor)
    {
        Current.AccentColor = accentColor;
        await NotifyAsync();
    }

    public async Task UpdateAsync(Theme theme, string accentColor)
    {
        Current.Theme = theme;
        Current.AccentColor = accentColor;
        await NotifyAsync();
    }

    private async Task NotifyAsync()
    {
        OnChange?.Invoke();
        await _cascadingSource.NotifyChangedAsync(Current);
    }
}

