arguments.file_text:
@rendermode InteractiveServer
@inject ThemeService ThemeSvc
@implements IDisposable

<span class="theme-indicator" style="color: @ThemeSvc.Current.AccentColor;" title="Current theme">
    @ThemeIcon @ThemeSvc.Current.Theme
</span>

@code {
    private string ThemeIcon => ThemeSvc.Current.Theme switch
    {
        Theme.Dark   => "🌙",
        Theme.System => "💻",
        _            => "☀️"
    };

    protected override void OnInitialized()
        => ThemeSvc.OnChange += OnThemeChanged;

    private void OnThemeChanged()
        => InvokeAsync(StateHasChanged);

    public void Dispose()
        => ThemeSvc.OnChange -= OnThemeChanged;
}

@rendermode InteractiveServer
@inject ThemeService ThemeSvc
@implements IDisposable

<button class="btn btn-sm btn-outline-light" @onclick="CycleTheme"
        title="Toggle theme" style="border-color: @ThemeSvc.Current.AccentColor;">
    @ThemeIcon
</button>

@code {
    private string ThemeIcon => ThemeSvc.Current.Theme switch
    {
        Theme.Dark   => "🌙",
        Theme.System => "💻",
        _            => "☀️"
    };

    private async Task CycleTheme()
    {
        var next = ThemeSvc.Current.Theme switch
        {
            Theme.Light  => Theme.Dark,
            Theme.Dark   => Theme.System,
            _            => Theme.Light
        };
        await ThemeSvc.SetThemeAsync(next);
    }

    protected override void OnInitialized()
        => ThemeSvc.OnChange += OnThemeChanged;

    private void OnThemeChanged()
        => InvokeAsync(StateHasChanged);

    public void Dispose()
        => ThemeSvc.OnChange -= OnThemeChanged;
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeSvc
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-3" style="max-width: 480px; border-color: @ThemeSvc.Current.AccentColor;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="btn-group mb-3" role="group">
            @foreach (var t in Enum.GetValues<Theme>())
            {
                <button class="btn @(ThemeSvc.Current.Theme == t ? "btn-primary" : "btn-outline-primary")"
                        @onclick="() => SelectTheme(t)">
                    @t
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>

        <div class="d-flex align-items-center gap-2 mb-3">
            <input type="color" class="form-control form-control-color"
                   value="@ThemeSvc.Current.AccentColor"
                   @onchange="OnColorChanged" />
            <span>@ThemeSvc.Current.AccentColor</span>
        </div>

        <h5 class="card-title mt-4">Preview</h5>
        <p>
            Current theme: <strong style="color: @ThemeSvc.Current.AccentColor;">@ThemeSvc.Current.Theme</strong>
        </p>
    </div>
</div>

@code {
    private async Task SelectTheme(Theme theme)
        => await ThemeSvc.SetThemeAsync(theme);

    private async Task OnColorChanged(ChangeEventArgs e)
        => await ThemeSvc.SetAccentColorAsync(e.Value?.ToString() ?? "#0d6efd");

    protected override void OnInitialized()
        => ThemeSvc.OnChange += OnThemeChanged;

    private void OnThemeChanged()
        => InvokeAsync(StateHasChanged);

    public void Dispose()
        => ThemeSvc.OnChange -= OnThemeChanged;
}

@rendermode InteractiveServer
@inject ThemeService ThemeSvc
@implements IDisposable

<span class="theme-indicator" style="color: @ThemeSvc.Current.AccentColor;" title="Current theme">
    @ThemeIcon @ThemeSvc.Current.Theme
</span>

@code {
    private string ThemeIcon => ThemeSvc.Current.Theme switch
    {
        Theme.Dark   => "🌙",
        Theme.System => "💻",
        _            => "☀️"
    };

    protected override void OnInitialized()
        => ThemeSvc.OnChange += OnThemeChanged;

    private void OnThemeChanged()
        => InvokeAsync(StateHasChanged);

    public void Dispose()
        => ThemeSvc.OnChange -= OnThemeChanged;
}

@rendermode InteractiveServer
@inject ThemeService ThemeSvc
@implements IDisposable

<button class="btn btn-sm btn-outline-light" @onclick="CycleTheme"
        title="Toggle theme" style="border-color: @ThemeSvc.Current.AccentColor;">
    @ThemeIcon
</button>

@code {
    private string ThemeIcon => ThemeSvc.Current.Theme switch
    {
        Theme.Dark   => "🌙",
        Theme.System => "💻",
        _            => "☀️"
    };

    private async Task CycleTheme()
    {
        var next = ThemeSvc.Current.Theme switch
        {
            Theme.Light  => Theme.Dark,
            Theme.Dark   => Theme.System,
            _            => Theme.Light
        };
        await ThemeSvc.SetThemeAsync(next);
    }

    protected override void OnInitialized()
        => ThemeSvc.OnChange += OnThemeChanged;

    private void OnThemeChanged()
        => InvokeAsync(StateHasChanged);

    public void Dispose()
        => ThemeSvc.OnChange -= OnThemeChanged;
}

